  // AC: @cli-exit-codes (exit 6 for warnings only)
  describe('exit code 6 (VALIDATION_WARNINGS)', () => {
    it('should exit 6 when only warnings are present (no errors)', () => {
      // The base fixtures have completeness warnings (missing ACs)
