      await fs.writeFile(
        path.join(cleanDir, 'project.tasks.yaml'),
        `tasks: []
`
      );
    });

    afterEach(async () => {
      await cleanupTempDir(cleanDir);
    });

    it('should exit 0 when project has no errors or warnings', () => {
